145	static std::tuple<ELFKind, uint16_t, uint8_t> parseEmulation(Ctx &ctx,
146	                                                             StringRef emul) {
147	  uint8_t osabi = 0;
148	  StringRef s = emul;
149	  if (s.ends_with("_fbsd")) {
150	    s = s.drop_back(5);
151	    osabi = ELFOSABI_FREEBSD;
152	  }
153	
154	  std::pair<ELFKind, uint16_t> ret =
155	      StringSwitch<std::pair<ELFKind, uint16_t>>(s)
156	          .Cases({"aarch64elf", "aarch64linux"}, {ELF64LEKind, EM_AARCH64})
157	          .Cases({"aarch64elfb", "aarch64linuxb"}, {ELF64BEKind, EM_AARCH64})
158	          .Cases({"armelf", "armelf_linux_eabi"}, {ELF32LEKind, EM_ARM})
159	          .Cases({"armelfb", "armelfb_linux_eabi"}, {ELF32BEKind, EM_ARM})
160	          .Case("elf32_x86_64", {ELF32LEKind, EM_X86_64})
161	          .Cases({"elf32btsmip", "elf32btsmipn32"}, {ELF32BEKind, EM_MIPS})
162	          .Cases({"elf32ltsmip", "elf32ltsmipn32"}, {ELF32LEKind, EM_MIPS})
163	          .Case("elf32lriscv", {ELF32LEKind, EM_RISCV})
164	          .Cases({"elf32ppc", "elf32ppclinux"}, {ELF32BEKind, EM_PPC})
165	          .Cases({"elf32lppc", "elf32lppclinux"}, {ELF32LEKind, EM_PPC})
166	          .Case("elf32loongarch", {ELF32LEKind, EM_LOONGARCH})
167	          .Case("elf64btsmip", {ELF64BEKind, EM_MIPS})
168	          .Case("elf64ltsmip", {ELF64LEKind, EM_MIPS})
169	          .Case("elf64lriscv", {ELF64LEKind, EM_RISCV})
170	          .Case("elf64ppc", {ELF64BEKind, EM_PPC64})
171	          .Case("elf64lppc", {ELF64LEKind, EM_PPC64})
172	          .Cases({"elf_amd64", "elf_x86_64"}, {ELF64LEKind, EM_X86_64})
173	          .Case("elf_i386", {ELF32LEKind, EM_386})
174	          .Case("elf_iamcu", {ELF32LEKind, EM_IAMCU})
175	          .Case("elf64_sparc", {ELF64BEKind, EM_SPARCV9})
176	          .Case("msp430elf", {ELF32LEKind, EM_MSP430})
177	          .Case("elf64_amdgpu", {ELF64LEKind, EM_AMDGPU})
178	          .Case("elf64loongarch", {ELF64LEKind, EM_LOONGARCH})
179	          .Case("elf64_s390", {ELF64BEKind, EM_S390})
180	          .Case("hexagonelf", {ELF32LEKind, EM_HEXAGON})
181	          .Default({ELFNoneKind, EM_NONE});
182	
183	  if (ret.first == ELFNoneKind)
184	    ErrAlways(ctx) << "unknown emulation: " << emul;
185	  if (ret.second == EM_MSP430)
186	    osabi = ELFOSABI_STANDALONE;
187	  else if (ret.second == EM_AMDGPU)
188	    osabi = ELFOSABI_AMDGPU_HSA;
189	  return std::make_tuple(ret.first, ret.second, osabi);
190	}
